/* Interactivity: the bridge drag (chapter 08) and ambient touch reactions.
   Transform/opacity only; effects go through the one FX canvas (particle cap 300). */
(function () {
  const $ = (id) => document.getElementById(id);

  // ---------- water / land lookup (config/watermask.js, generated by scripts/make-watermask.mjs) ----------
  let mask = null;
  function loadMask() {
    const M = window.VALU_WATERMASK;
    if (!M || !M.bits) return;
    const bin = atob(M.bits), bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    mask = { w: M.w, h: M.h, cell: M.cell, bytes };
  }
  V.isWater = (x, y) => {
    if (!mask) return false;
    const cx = Math.floor(x / mask.cell), cy = Math.floor(y / mask.cell);
    if (cx < 0 || cy < 0 || cx >= mask.w || cy >= mask.h) return true; // beyond the picture: sea
    const i = cy * mask.w + cx;
    return (mask.bytes[i >> 3] >> (7 - (i & 7))) & 1;
  };
  loadMask();

  // ---------- bridge drag ----------
  // A Spark rests at the Egypt end of the bridge. Drag it along the bridge: it snaps to the path and
  // follows the finger. Let go early → it eases home. Reach Jordan → bridge pulse, the 08 card, Jordan lights up.
  const BD = (V.bridgeDrag = {});
  const layer = $("drag");
  const el = V.el("div", "bspark");
  el.innerHTML = `<div class="bspark-halo"></div>`;
  el.appendChild(V.art.spark({ size: 54 }).el); // never rotated: only moved
  const ghost = V.el("div", "bghost");
  layer.append(el, ghost);
  let path = null, pts = null, t = 0, state = "idle", owner = null, stopTween = null, lastTrail = 0;

  function place(tt) {
    t = V.clamp(tt, 0, 1);
    const p = path.at(t);
    el.style.transform = `translate(${p.x}px,${p.y}px)`;
    return p;
  }
  // Parameter (0..1) of the point on the bridge path closest to (x, y).
  function project(x, y) {
    let best = 0, bd = Infinity, acc = 0;
    for (let i = 1; i < pts.length; i++) {
      const [ax, ay] = pts[i - 1], [bx, by] = pts[i], dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy || 1, l = Math.sqrt(l2);
      const k = V.clamp(((x - ax) * dx + (y - ay) * dy) / l2, 0, 1);
      const d = Math.hypot(x - (ax + dx * k), y - (ay + dy * k));
      if (d < bd) { bd = d; best = (acc + k * l) / path.len; }
      acc += l;
    }
    return best;
  }
  BD.ready = () => !!path;
  BD.state = () => state;
  BD.t = () => t;
  BD.reset = () => {
    stopTween && stopTween();
    pts = (V.layout.paths.bridge || []).slice();
    path = pts.length > 1 ? V.path(pts) : null;
    state = "idle"; owner = null;
    el.style.display = path ? "" : "none";
    ghost.style.opacity = 0;
    el.style.opacity = 1;
    el.classList.remove("dragging");
    if (path) place(0);
  };
  function goHome() {
    state = "return";
    const t0 = t;
    stopTween = V.tween(600, (k) => place(t0 * (1 - k)), { ease: V.ease.outCubic, done: () => { state = "idle"; } });
  }
  function arrive(touch) {
    state = "arrived"; owner = null;
    el.classList.remove("dragging");
    const end = place(1);
    V.audio.chime();
    V.fx.ring(end.x, end.y, { r1: 100, dur: 800, color: "orange", width: 5 });
    V.fx.sparkle(end.x, end.y, { n: 14, spread: 40 });
    V.world.bridgePulse(true).then(() => V.story.showHeadline());
    V.world.jordanLights();
    if (touch && !V.story.isOpen(8)) V.story.openCard(8, { touch });
    // after a moment the Spark fades out at Jordan and reappears at the Egypt end
    setTimeout(() => {
      if (state !== "arrived") return;
      stopTween = V.tween(400, (k) => { el.style.opacity = 1 - k; }, { done: () => {
        place(0);
        stopTween = V.tween(500, (k) => { el.style.opacity = k; }, { done: () => { state = "idle"; } });
      } });
    }, 2600);
  }

  el.addEventListener("pointerdown", (e) => {
    e.stopPropagation(); // never reaches the world tap layer
    if (V.editing || owner != null || state === "arrived" || state === "auto" || !path) return;
    owner = e.pointerId;
    try { el.setPointerCapture(e.pointerId); } catch (err) {}
    stopTween && stopTween();
    state = "drag";
    el.classList.add("dragging");
    V.audio.tick();
  });
  el.addEventListener("pointermove", (e) => {
    if (e.pointerId !== owner || state !== "drag") return;
    const [x, y] = V.cam.toWorld(...V.stage.toStage(e.clientX, e.clientY));
    const p = place(project(x, y));
    if (V.now() - lastTrail > 60) { lastTrail = V.now(); V.fx.sparkle(p.x, p.y, { n: 1, spread: 8, scale: 0.8, stagger: 0 }); }
    if (t >= 0.97) arrive([x, y]);
  });
  const release = (e) => {
    if (e.pointerId !== owner) return;
    owner = null;
    el.classList.remove("dragging");
    if (state === "drag") goHome();
  };
  el.addEventListener("pointerup", release);
  el.addEventListener("pointercancel", release);
  el.addEventListener("lostpointercapture", release);

  // The tour drags it itself, with a faint ghost-finger dot. Resolves when done (or when the tour stops).
  BD.auto = (alive) => new Promise((resolve) => {
    if (!path || state !== "idle") { resolve(); return; }
    state = "auto";
    ghost.style.opacity = 0;
    const show = (k) => { const p = place(k); ghost.style.transform = `translate(${p.x + 16}px,${p.y + 20}px)`; };
    show(0);
    V.tween(300, (k) => { ghost.style.opacity = 0.55 * k; });
    stopTween = V.tween(2300, (k) => {
      if (!alive()) return;
      show(k);
    }, { delay: 350, ease: V.ease.inOutSine, done: () => {
      V.tween(300, (k) => { ghost.style.opacity = 0.55 * (1 - k); });
      if (!alive()) { goHome(); resolve(); return; }
      arrive(null);
      setTimeout(resolve, 700);
    } });
  });

  // ---------- ambient touch ----------
  // A touch that hits no story point: water ripples, a puff of sparks on land, or a hop for a car/boat/plane.
  // At most 4 reactions per finger per second (a finger = taps within 120 px of each other).
  const AM = (V.ambient = {});
  const recent = [];
  AM.react = (x, y) => {
    if (V.set().ambientTouch === false) { V.fx.ring(x, y, { r1: 40, dur: 600, color: "white", width: 3 }); return; }
    const now = V.now();
    while (recent.length && now - recent[0].t > 1000) recent.shift();
    if (recent.filter((r) => Math.hypot(r.x - x, r.y - y) < 120).length >= 4) return;
    recent.push({ x, y, t: now });
    const m = V.world.moverAt(x, y);
    if (m) { V.world.hop(m); V.audio.tick(); return; }
    if (V.isWater(x, y)) {
      const n = Math.random() < 0.5 ? 2 : 3;
      for (let i = 0; i < n; i++) V.fx.ring(x, y, { r1: 34 + i * 18, dur: 700 + i * 120, color: "white", width: 3 - i * 0.6, delay: i * 0.12 });
    } else {
      V.fx.burst(x, y, { n: 6 + ((Math.random() * 5) | 0), color: ["orange", "teal"], speed: 110, size: 4, life: 0.6, drag: 3 });
    }
  };
})();
